mapper.select:
SELECT a.ACCOUNT prdCode, count(INDENTIFY_MARK) CustHeldNum from ( select ACCOUNT , INDENTIFY_MARK, STATUS, ROW_NUMBER() over( partition BY ACCOUNT, INDENTIFY_MARK ORDER BY UPDATE_TIME DESC) AS rowno from CHB_EQUDET
AND ACCOUNT IN
